<script setup lang="ts">
import { compareAddresses } from './logic'

const EXAMPLES = {
  same: ['UQCD39VS5jcptHL8vMjEXrzGaRcCVYto7HUn4bpAOg8xqEBI', '0:83dfd552e63729b472fcbcc8c45ebcc6691702558b68ec7527e1ba403a0f31a8'],
  different: ['UQCD39VS5jcptHL8vMjEXrzGaRcCVYto7HUn4bpAOg8xqEBI', 'UQCdqXGvONLwOr3zCNX5FjapflorB6ZsOdcdfLrjsDLt3AF4'],
  // A look-alike generated by brute force to match the first and last 4 characters (no one owns it).
  lookalike: ['UQCD39VS5jcptHL8vMjEXrzGaRcCVYto7HUn4bpAOg8xqEBI', 'UQCDdHhuaoYr8YWq3hzV73PRsiMMSfincOTCxxIelOkaqEBI']
}

const a = ref('')
const b = ref('')

const result = computed(() => {
  if (!a.value.trim() || !b.value.trim()) return null
  try {
    return { ok: true as const, data: compareAddresses(a.value, b.value) }
  }
  catch (e) {
    return { ok: false as const, error: (e as Error).message }
  }
})

const verdict = computed(() => {
  const d = result.value?.ok ? result.value.data : null
  if (!d) return null
  if (d.same) return { color: 'success' as const, icon: 'i-lucide-circle-check', title: 'Same account', text: 'Both addresses point to the same account. Funds sent to either one arrive in the same place.' }
  if (d.risk === 'lookalike') {
    return { color: 'error' as const, icon: 'i-lucide-skull', title: 'Different accounts that look alike: likely address poisoning', text: `They share the first ${d.prefix} and last ${d.suffix} characters, which is what most wallets show. Scammers create such addresses and send you a tiny transfer so the fake one sits in your history. Do not copy addresses from your transaction history.` }
  }
  if (d.risk === 'similar') {
    return { color: 'warning' as const, icon: 'i-lucide-triangle-alert', title: 'Different accounts, partly similar', text: `They share ${d.prefix} starting and ${d.suffix} ending characters. Make sure you have the right one before sending.` }
  }
  return { color: 'error' as const, icon: 'i-lucide-circle-x', title: 'Different accounts', text: 'These are two different accounts. Funds sent to one will not reach the other.' }
})

function short(s: string) {
  return s.length > 12 ? `${s.slice(0, 4)}…${s.slice(-4)}` : s
}

function load(k: keyof typeof EXAMPLES) {
  [a.value, b.value] = EXAMPLES[k] as [string, string]
}

function swap() {
  [a.value, b.value] = [b.value, a.value]
}
</script>

<template>
  <div class="space-y-6">
    <div class="space-y-3">
      <AddressInput v-model="a" label="Address A" placeholder="The address you expect (e.g. from the recipient)" />
      <div class="flex justify-center">
        <UButton icon="i-lucide-arrow-up-down" color="neutral" variant="ghost" size="sm" aria-label="Swap A and B" :disabled="!a && !b" @click="swap" />
      </div>
      <AddressInput v-model="b" label="Address B" placeholder="The address you are about to send to" />
      <div v-if="!a && !b" class="flex flex-wrap gap-x-4">
        <UButton label="Example: same account" icon="i-lucide-sparkles" variant="link" size="sm" class="px-0" @click="load('same')" />
        <UButton label="Example: different accounts" icon="i-lucide-sparkles" variant="link" size="sm" class="px-0" @click="load('different')" />
        <UButton label="Example: look-alike" icon="i-lucide-sparkles" variant="link" size="sm" class="px-0" @click="load('lookalike')" />
      </div>
    </div>

    <UAlert v-if="result && !result.ok" color="error" variant="subtle" icon="i-lucide-triangle-alert" :title="result.error" />

    <template v-if="result?.ok && verdict">
      <UAlert :color="verdict.color" variant="subtle" :icon="verdict.icon" :title="verdict.title" :description="verdict.text" :ui="{ title: 'text-base font-semibold' }" />

      <ul v-if="result.data.flagNotes.length" class="list-disc space-y-1 pl-5 text-sm text-muted">
        <li v-for="n in result.data.flagNotes" :key="n">
          {{ n }}
        </li>
      </ul>

      <div class="space-y-3">
        <div class="text-xs text-muted">
          Character by character, both written in the same form as A
          <span v-if="!result.data.same">({{ result.data.differing }} of {{ result.data.shownA.length }} characters differ)</span>
        </div>
        <div v-for="(row, i) in [result.data.diffA, result.data.diffB]" :key="i" class="flex items-start gap-3">
          <span class="mt-0.5 w-4 shrink-0 font-display text-sm font-semibold text-muted">{{ i ? 'B' : 'A' }}</span>
          <code class="font-mono text-sm leading-6 break-all"><span
            v-for="(c, j) in row"
            :key="j"
            :class="c.same ? 'text-default' : 'rounded-sm bg-error/15 font-semibold text-error'"
          >{{ c.char }}</span></code>
        </div>
        <div class="text-xs text-dimmed">
          What a wallet typically shows: A <span class="font-mono">{{ short(result.data.shownA) }}</span>, B <span class="font-mono">{{ short(result.data.shownB) }}</span>
        </div>
      </div>
    </template>

    <div class="rounded-lg border border-default p-4 text-sm text-muted">
      <div class="font-semibold text-highlighted">
        How address poisoning works
      </div>
      <p class="mt-1">
        Wallets shorten addresses to a few characters at each end. Scammers generate an address with the same start and end as someone you pay, then send you a tiny amount or a fake token so it appears in your history. If you copy from history, your next payment goes to them. Always take the address from the original source, and compare the full string here when in doubt.
      </p>
    </div>
  </div>
</template>
